-- Enlaces de X · Tecnologías de punta (página pública /tecnologias-de-punta).
create table if not exists public.enlace_x (
  id bigserial primary key,
  tweet_id text not null unique,
  enlace text not null,
  cuenta text not null,
  autor text not null,
  fecha timestamptz not null default now(),
  titulo text not null check (char_length(titulo) between 1 and 200),
  resumen text not null default '' check (char_length(resumen) <= 2000),
  nota text check (char_length(nota) <= 1000),
  categoria text not null check (categoria in ('cursor','modelos','agentes','diseno','infra','tips')),
  registrado_por text,
  eliminado boolean not null default false,
  eliminado_por text,
  eliminado_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists enlace_x_fecha_idx on public.enlace_x (fecha desc) where not eliminado;

alter table public.enlace_x enable row level security;

on conflict (tweet_id) do nothing;
