insert into public.enlace_x (tweet_id, enlace, cuenta, autor, fecha, titulo, resumen, nota, categoria, registrado_por) values
  ('1957977611646439628', 'https://x.com/leerob/status/1957977611646439628', 'leerob', 'Lee Robinson', '2025-08-20T09:00:00-06:00', 'Nuevo modelo “sigiloso” gratis en Cursor', 'Hay un nuevo modelo experimental en Cursor de uno de sus socios. Es gratis para probarlo y piden comentarios sobre qué tal funciona.', 'Tienen que activar este agente en Cursor. Es gratis y parece ser la beta del nuevo agente especializado de Grok para programación.', 'modelos', 'Slack · Dirección General'),
  ('1961037386198266258', 'https://x.com/tetsuoai/status/1961037386198266258', 'tetsuoai', 'Tetsuo', '2025-08-28T13:29:00-06:00', 'Grok Code, gratis en editores como Cursor', 'Grok Code es un modelo disponible en editores como Cursor y, por ahora, también es gratuito.', null, 'modelos', 'Slack · Dirección General'),
  ('1972680165378650391', 'https://x.com/lovable_dev/status/1972680165378650391', 'lovable_dev', 'Lovable', '2025-09-29T12:30:00-06:00', 'Lovable Cloud & AI: apps con backend solo con instrucciones', 'Presentan Lovable Cloud & AI, un nuevo capítulo del “vibe coding”: cualquiera puede crear apps con IA avanzada y backend solo describiendo lo que quiere. Cada día se construyen más de 100 mil ideas, herramientas y sitios en Lovable.', null, 'infra', 'Slack · Dirección General'),
  ('1983567619946147967', 'https://x.com/cursor_ai/status/1983567619946147967', 'cursor_ai', 'Cursor', '2025-10-29T21:48:00-06:00', 'Llega Cursor 2.0 con su primer modelo propio', 'Presentan Cursor 2.0: su primer modelo de programación y la mejor forma de programar con agentes.', null, 'cursor', 'Slack · Dirección General'),
  ('1983573794414555314', 'https://x.com/corbin_braun/status/1983573794414555314', 'corbin_braun', 'Corbin', '2025-10-29T22:18:00-06:00', 'El navegador de Cursor 2.0: “Paint para desarrolladores”', 'La función de navegador de Cursor 2.0 es básicamente un Paint para desarrolladores: señalas partes de la página, dices “quiero cambiar esto” y simplemente funciona. El desarrollo frontend se vuelve tan intuitivo como dibujar.', null, 'cursor', 'Slack · Dirección General'),
  ('1984260161008202051', 'https://x.com/leerob/status/1984260161008202051', 'leerob', 'Lee Robinson', '2025-10-31T12:14:00-06:00', 'Cursor ya trae navegador web integrado', 'Puedes decir “arranca mi app” y Cursor levanta el servidor en una terminal y abre el navegador en localhost:3000. Toma capturas para iterar el diseño y puedes mandarle elementos de la página al agente junto con tus instrucciones.', null, 'cursor', 'Slack · Dirección General'),
  ('1984254784640278635', 'https://x.com/filiksyos/status/1984254784640278635', 'filiksyos', 'Fili', '2025-10-31T12:44:00-06:00', 'Tip: usa /summarize cuando el contexto llegue al 50 %', 'Tip de Cursor que cambia el juego: cuando el contexto llegue a ~50 %, escribe el comando /summarize. Ahorra dinero y mantiene precisas las respuestas de la IA.', null, 'tips', 'Slack · Dirección General'),
  ('1997528999010897974', 'https://x.com/marionawfal/status/1997528999010897974', 'marionawfal', 'Mario Nawfal', '2025-12-08T21:23:00-06:00', 'Grok tendrá entorno de programación e integración con GitHub', 'Grok está lanzando conexión nativa con GitHub y un espacio real de programación: podrás traer repositorios, editar código, hacer commit y push, todo dentro de Grok, impulsado por Grok Code.', null, 'modelos', 'Slack · Dirección General'),
  ('1999147953609736464', 'https://x.com/cursor_ai/status/1999147953609736464', 'cursor_ai', 'Cursor', '2025-12-12T09:15:00-06:00', 'Diseña directo en tu código con Cursor', 'Ahora puedes diseñar directamente en tu código: seleccionas elementos, los modificas visualmente y Cursor escribe el código.', null, 'diseno', 'Slack · Dirección General'),
  ('2026658264264696155', 'https://x.com/heynavtoor/status/2026658264264696155', 'heynavtoor', 'Nav Toor', '2026-02-25T23:20:00-06:00', 'CodexBar: tus límites de uso de IA en tiempo real', 'Alguien creó la herramienta que todo programador con IA pedía: CodexBar, una pequeña app para la barra de menú de macOS que muestra en tiempo real tus límites de uso de IA. Se acabó el “¿por qué dejó de funcionar Claude Code?” y entrar a paneles para revisarlo.', 'Esto les podría servir.', 'tips', 'Slack · Dirección General'),
  ('2023827905743384969', 'https://x.com/cursor_ai/status/2023827905743384969', 'cursor_ai', 'Cursor', '2026-02-27T22:55:00-06:00', 'Plugin de Vercel: buenas prácticas de React en Cursor', 'Optimiza tus apps aplicando las mejores prácticas de React con el plugin de Vercel para Cursor.', null, 'cursor', 'Slack · Dirección General'),
  ('2026198305362083910', 'https://x.com/hartdrawss/status/2026198305362083910', 'hartdrawss', 'Harshil Tomar', '2026-02-28T12:59:00-06:00', 'Vibe Coding 2.0: 18 reglas para estar en el top 1 %', 'Artículo con 18 reglas prácticas para programar con IA y estar entre el 1 % de los mejores creadores.', null, 'tips', 'Slack · Dirección General'),
  ('2027579258328256574', 'https://x.com/itsandrewgao/status/2027579258328256574', 'itsandrewgao', 'Andrew Gao', '2026-02-28T13:10:00-06:00', 'Documento de referencia para diseños frontend', 'Publicación con un documento enlazado sobre diseño de interfaces; ideal para que una IA lo estudie y lo aplique en el frontend.', 'Pídanle a una IA que estudie este documento. Chéquenlo, está muy interesante para los diseños de front end.', 'diseno', 'Slack · Dirección General'),
  ('2027781154729037932', 'https://x.com/morganlinton/status/2027781154729037932', 'morganlinton', 'Morgan', '2026-02-28T20:28:00-06:00', 'Lectura obligada del fundador de Cursor', 'Recomiendan un texto del fundador de Cursor sobre la dirección del producto y sus nuevas funciones.', 'Nueva función de Cursor.', 'cursor', 'Slack · Dirección General'),
  ('2029604184002269662', 'https://x.com/cursor_ai/status/2029604184002269662', 'cursor_ai', 'Cursor', '2026-03-05T13:17:00-06:00', 'Automations: Cursor vigila y mejora tu código solo', 'Cursor ahora puede monitorear y mejorar tu código de forma continua. Las automatizaciones se ejecutan según los disparadores e instrucciones que tú defines.', 'Revisen esto, importante.', 'agentes', 'Slack · Dirección General'),
  ('2029607757658411272', 'https://x.com/austinnickpiel/status/2029607757658411272', 'austinnickpiel', 'Austin Nick Piel', '2026-03-06T09:00:00-06:00', 'Revisión de código 100 % con Automations', 'Movieron todo su ciclo de revisión de código a Automations: Cursor aprueba los cambios de bajo riesgo y asigna revisores automáticamente, según el historial de commits, a los de riesgo medio o alto.', 'Para todo el canal.', 'agentes', 'Slack · Dirección General'),
  ('2031784967685218684', 'https://x.com/githubprojects/status/2031784967685218684', 'githubprojects', 'GitHub Projects Community', '2026-03-11T16:14:00-06:00', 'El “flujo real” del vibe coding (en humor)', 'Un árbol de carpetas en broma: preparar (abrir Cursor, abrir ChatGPT, café, “construyamos algo”), desarrollar (prompt, otro prompt, refinar prompt, uno más, copiar y pegar código) y depurar…', null, 'tips', 'Slack · Dirección General'),
  ('2034075096495886477', 'https://x.com/vercel_dev/status/2034075096495886477', 'vercel_dev', 'Vercel Developers', '2026-03-19T08:00:00-06:00', 'Plugin de Vercel para agentes: 47+ habilidades con un comando', 'Un plugin, un comando, todas las habilidades: npx plugins add vercel/vercel-plugin. Convierte capacidades sueltas en experiencia coordinada con más de 47 habilidades especializadas, subagentes para despliegues y rendimiento, y contexto dinámico.', 'Prueben implementar esto hoy.', 'agentes', 'Slack · Dirección General'),
  ('2035728142095339677', 'https://x.com/ataiiam/status/2035728142095339677', 'ataiiam', 'Atai Barkai', '2026-03-23T09:00:00-06:00', 'Shadify: interfaces generativas con ShadCN', 'Describe una interfaz y un agente de LangChain la arma al momento con componentes de ShadCN, usando AG-UI y CopilotKit. Después la exportas como código React.', 'Chequen si se puede integrar esto para que sus agentes lo usen de forma automática.', 'diseno', 'Slack · Dirección General'),
  ('2034515384003694761', 'https://x.com/_vmlops/status/2034515384003694761', '_vmlops', 'Vaishnavi', '2026-03-23T09:00:00-06:00', 'UI/UX Pro Max: sistemas de diseño para tu IA', 'Aprender UI/UX suele ser adivinar qué se ve bien. Este repositorio lo cambia: la skill UI/UX Pro Max da sistemas de diseño, estilos y reglas estructuradas según tu producto. Menos adivinar, más construir.', 'Agreguen esto para front end también.', 'diseno', 'Slack · Dirección General'),
  ('2036375450398892405', 'https://x.com/ericzakariasson/status/2036375450398892405', 'ericzakariasson', 'Eric Zakariasson', '2026-03-24T07:23:00-06:00', 'Artículo: cómo trabajar mejor con agentes', 'Enlace a un artículo completo de Eric Zakariasson (Cursor) sobre flujos de trabajo con agentes de IA.', 'Pregunten a sus agentes que lean este artículo y cómo podrían usarlo para sus sistemas.', 'agentes', 'Slack · Dirección General'),
  ('2039476192169112027', 'https://x.com/hasantoxr/status/2039476192169112027', 'hasantoxr', 'Hasan Toor', '2026-04-08T09:00:00-06:00', 'awesome-design-md: “el Figma para agentes de IA”', 'Colección de archivos DESIGN.md extraídos de 31 sitios reales que los agentes de programación sí pueden leer. Sin exportar de Figma, sin esquemas JSON ni herramientas especiales: solo un archivo markdown.', 'Chequen esto.', 'diseno', 'Slack · Dirección General'),
  ('2039768512894505086', 'https://x.com/cursor_ai/status/2039768512894505086', 'cursor_ai', 'Cursor', '2026-04-09T09:00:00-06:00', 'Llega Cursor 3', 'Cursor 3 es más simple, más potente y está hecho para un mundo donde todo el código lo escriben agentes, sin perder la profundidad de un entorno de desarrollo.', 'Revisen el curso de Cursor para ver si se actualizó.', 'cursor', 'Slack · Dirección General'),
  ('2039573042553102659', 'https://x.com/tom_doerr/status/2039573042553102659', 'tom_doerr', 'Tom Dörr', '2026-04-10T09:00:00-06:00', 'Búsqueda por palabras clave en árboles de documentos', 'Herramienta de código abierto para buscar por palabras clave dentro de estructuras de documentos.', '¿Chequen si esto no les sirve?', 'tips', 'Slack · Dirección General'),
  ('2043373611114020909', 'https://x.com/ihtesham2005/status/2043373611114020909', 'ihtesham2005', 'Ihtesham Ali', '2026-04-13T09:00:00-06:00', 'three-man-team: un equipo de 3 agentes de IA', 'Alguien construyó un equipo de desarrollo de 3 agentes basado en 20 años de experiencia en producción y lo liberó completo. Todo cabe en tres archivos de contexto. Resuelve que las herramientas de IA son potentes pero indisciplinadas.', 'Revisen esto, se ve bien.', 'agentes', 'Slack · Dirección General'),
  ('2062689734321688920', 'https://x.com/precisox/status/2062689734321688920', 'precisox', 'precis0x', '2026-06-05T08:25:00-06:00', 'Memanto: memoria persistente para tus agentes', 'Un equipo de desarrolladores autodidactas creó Memanto, herramienta de código abierto que da memoria infinita y persistente a tus IAs, para que no olviden todo cada vez que cierras la pestaña.', 'Para todo el canal.', 'agentes', 'Slack · Dirección General'),
  ('2067192475853180997', 'https://x.com/opendesignhq/status/2067192475853180997', 'opendesignhq', 'Open Design', '2026-06-17T10:17:00-06:00', 'Open Design: estudio de diseño con IA, de código abierto', 'El diseño estilo Cursor ya es real y lo liberaron para todos: señala, comenta, marca, edita, captura y remezcla. Deja que la IA diseñe por ti y toma el control cuando quieras.', null, 'diseno', 'Slack · Dirección General'),
  ('2067180054979936413', 'https://x.com/vercel/status/2067180054979936413', 'vercel', 'Vercel', '2026-06-17T13:27:00-06:00', 'Vercel lanza Eve, framework para construir agentes', 'Eve es un framework de código abierto para construir agentes. Cada agente tiene instrucciones (quién es y cómo se comporta), herramientas (para interactuar con sistemas externos) y skills (procedimientos reutilizables para tareas).', 'Cárguenle esto a sus agentes. Pídanle que lo integre a su flujo de trabajo actual.', 'agentes', 'Slack · Dirección General'),
  ('2067310428682928358', 'https://x.com/wholemars/status/2067310428682928358', 'wholemars', 'Whole Mars Catalog', '2026-06-17T21:27:00-06:00', 'Cursor Composer ahora es Grok Composer', 'El modelo Composer de Cursor pasa a llamarse Grok Composer.', null, 'modelos', 'Slack · Dirección General'),
  ('2067996575817945197', 'https://x.com/datachaz/status/2067996575817945197', 'datachaz', 'Charly Wargnier', '2026-06-20T12:08:00-06:00', 'Headroom: hasta 95 % menos tokens sin cambiar código', 'Un ingeniero de Netflix liberó Headroom, una de las formas más inteligentes de bajar costos de LLM: envuelve a Cursor o Claude en un proxy local que comprime lo que envías antes de llegar al modelo.', 'A ver, chequen esto.', 'tips', 'Slack · Dirección General'),
  ('2068328135611822149', 'https://x.com/anatolikopadze/status/2068328135611822149', 'anatolikopadze', 'Anatoli Kopadze', '2026-06-21T08:57:00-06:00', 'Loops explicados: Claude, GPT, Mira y lo que sí funciona', 'Artículo que explica los ciclos de trabajo de los agentes (loops) en Claude, GPT y Mira, y qué enfoques funcionan en la práctica.', null, 'agentes', 'Slack · Dirección General'),
  ('2069410910435991749', 'https://x.com/connect24h/status/2069410910435991749', 'connect24h', 'connect24h', '2026-06-24T09:10:00-06:00', 'DESIGN.md de Google: la IA entiende tu diseño a la primera', 'Decirle 10 veces a la IA “hazme una UI bonita” no funcionaba; con un solo archivo DESIGN.md de Google salió a la primera. Define los tokens en YAML y explica en prosa por qué cada valor. Adiós a las instrucciones que dependen de cada persona.', 'Revisen si esto vale la pena.', 'diseno', 'Slack · Dirección General'),
  ('2070016711341040054', 'https://x.com/aiedge_/status/2070016711341040054', 'aiedge_', 'AI Edge', '2026-06-26T09:37:00-06:00', 'Skill “Taste”: adiós al diseño genérico de IA', 'Un framework frontend “anti-slop” impresionante: dale la skill “Taste” a tu agente (Hermes, Claude Code o Codex) para eliminar el diseño genérico de IA. Incluye skills de diseño, generación de imágenes y más.', 'Quiero ver que probemos este.', 'diseno', 'Slack · Dirección General'),
  ('2075686268113916023', 'https://x.com/cursor_ai/status/2075686268113916023', 'cursor_ai', 'Cursor', '2026-07-11T07:34:00-06:00', 'Chats laterales en Cursor', 'Nueva forma de hacer preguntas y explorar ideas sin interrumpir tu conversación principal. Cada chat lateral es una conversación con el agente que perdura y puedes mencionar con @ para traer su contexto al hilo principal.', null, 'cursor', 'Slack · Dirección General'),
  ('2077552106014154846', 'https://x.com/leerob/status/2077552106014154846', 'leerob', 'Lee Robinson', '2026-07-15T21:39:00-06:00', 'Cursor duplica el uso incluido de sus modelos', 'Se duplicó el uso incluido de los modelos de Cursor en todos los planes: más acceso a Grok 4.5 y Composer 2.5.', null, 'modelos', 'Slack · Dirección General'),
  ('2077824029126504525', 'https://x.com/arena/status/2077824029126504525', 'arena', 'Arena.ai', '2026-07-16T13:36:00-06:00', 'Kimi-K3, #1 en la arena de código frontend', 'Kimi-K3 de Moonshot es ahora el #1 en Frontend Code Arena con 1679 puntos, superando a Claude Fable 5: un salto de 17 lugares desde Kimi-k2.6. Quedó #1 en 6 de 7 categorías, como marca y marketing, diseño con referencias y datos y analítica.', null, 'modelos', 'Slack · Dirección General'),
  ('2078774556249186345', 'https://x.com/thesupermanmx/status/2078774556249186345', 'thesupermanmx', 'Superman', '2026-07-20T09:00:00-06:00', 'Unlimited-OCR: lee PDFs de 100 páginas de una vez', 'China liberó un OCR diminuto que procesa PDFs completos de 100 páginas en una sola pasada. Se llama Unlimited-OCR, tiene solo 3B de parámetros y corre en local, sin perder el hilo entre páginas.', null, 'modelos', 'Slack · Dirección General'),
  ('2080001007979757618', 'https://x.com/davep/status/2080001007979757618', 'davep', 'David Pan', '2026-07-23T10:27:00-06:00', 'Cursor Router elige el mejor modelo para cada tarea', 'Ya no necesitas ser experto en benchmarks, niveles de razonamiento ni caché. Cursor Router elige el modelo para cada tarea según la calidad medida contra el costo, con rendimiento nivel Fable 5.', null, 'cursor', 'Slack · Dirección General'),
  ('2085464617694777762', 'https://x.com/cursor_ai/status/2085464617694777762', 'cursor_ai', 'Cursor', '2026-08-06T16:09:00-06:00', 'Cursor soporta Agent Plugins', 'Cursor ahora soporta Agent Plugins, un estándar abierto para empaquetar skills y servidores MCP y usarlos entre distintos agentes.', null, 'agentes', 'Slack · Dirección General'),
  ('2087296100545782192', 'https://x.com/ericksky/status/2087296100545782192', 'ericksky', 'Erick', '2026-08-12T01:35:00-06:00', 'Depurar ya no es lo que era, gracias a la IA', 'Jarred Sumner (creador de Bun) recordó un tweet de 2022 donde pasó 3 horas depurando un bug de JavaScript; hoy dice que “eso ya no pasa”. Boris, creador de Claude Code, responde con una verdad incómoda sobre cómo cambió el trabajo.', null, 'tips', 'Slack · Dirección General'),
  ('2087565405191635168', 'https://x.com/ericksky/status/2087565405191635168', 'ericksky', 'Erick', '2026-08-12T10:21:00-06:00', 'Grok 4.6 con uso doble en Cursor y Grok', 'Llega Grok 4.6 y por tiempo limitado duplicaron el uso en los planes de Cursor y Grok. Rinde como Fable 5 o GPT-5.6 SOL en MAX, pero pensado para uso intensivo.', null, 'modelos', 'Slack · Dirección General'),
  ('2087613483038683193', 'https://x.com/mosheabram38005/status/2087613483038683193', 'mosheabram38005', 'Moshe Abramovitch', '2026-08-13T12:46:00-06:00', 'Más de 300 skills de NVIDIA en Cursor', 'Agrega el plugin de NVIDIA y tu agente obtiene más de 300 skills en más de 30 productos (CUDA, NeMo, RAG). Dile qué construyes y propone la skill correcta.', null, 'agentes', 'Slack · Dirección General'),
  ('2089399059488350447', 'https://x.com/cursor_ai/status/2089399059488350447', 'cursor_ai', 'Cursor', '2026-08-19T09:30:00-06:00', 'Origin se integra con Vercel, Buildkite y Depot', 'Se asociaron con algunas de las mejores integraciones de GitHub: Vercel, Buildkite y Depot ya están disponibles y vienen más.', 'Arranquemos hoy. Revisen todos los que están marcados con anteriores; no me han confirmado si ya revisaron los anteriores.', 'infra', 'Slack · Dirección General'),
  ('2089466749943152806', 'https://x.com/ericzakariasson/status/2089466749943152806', 'ericzakariasson', 'Eric Zakariasson', '2026-08-19T09:30:00-06:00', 'Origin ya está disponible para alojar tu código', 'Origin está en vivo y listo para alojar tu código; incluye una guía de cómo empezar.', 'Lean esto al respecto.', 'infra', 'Slack · Dirección General'),
  ('2090136956101414982', 'https://x.com/cursor_ai/status/2090136956101414982', 'cursor_ai', 'Cursor', '2026-08-19T13:27:00-06:00', 'Agentes en la nube de Cursor, más autónomos', 'Siguen mejorando los agentes en la nube: toman trabajo a partir de eventos, mantienen un objetivo hasta cumplirlo y no se desvían en sesiones largas.', null, 'agentes', 'Slack · Dirección General'),
  ('2093077548649570777', 'https://x.com/cursor_ai/status/2093077548649570777', 'cursor_ai', 'Cursor', '2026-08-27T17:01:00-06:00', 'Crea, guarda y publica apps: Cursor + Origin + Vercel', 'Ahora puedes crear apps web nuevas con Cursor, guardar el código en Origin y publicarlas en Vercel.', null, 'infra', 'Slack · Dirección General'),
  ('2098162488013455784', 'https://x.com/cursor_ai/status/2098162488013455784', 'cursor_ai', 'Cursor', '2026-09-11T09:00:00-06:00', 'Projects: un agente coordinador siempre activo', 'En lugar de abrir un chat por tarea, trabajas con un agente coordinador en un solo hilo persistente. Siempre está activo, gestiona el trabajo con subagentes de forma proactiva y mejora con el tiempo.', 'Revisen esto.', 'cursor', 'Slack · Dirección General'),
  ('2104949571789148416', 'https://x.com/hanghuang_/status/2104949571789148416', 'hanghuang_', 'Hang Huang', '2026-09-29T12:47:00-06:00', 'InstaCloud: nube serverless pensada para agentes', 'Levantaron 8 millones de dólares para competir con AWS, GCP y Azure. InstaCloud es una nube serverless nativa para agentes que elimina el trabajo manual y tedioso de DevOps al desplegar.', null, 'infra', 'Slack · Dirección General')
